using Godot;
using System;
using System.Collections.Generic;
using System.Linq;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class PowderSolverOperations:RefCounted
{
    private static Variant Get(Settings values,string key,Variant fallback=default)=>values.TryGetValue(key,out var value)?value:fallback;
    private sealed class Batch
    {
        internal Settings Row,State,Settings,Config;internal int[] Ids,Contacts;internal float[] Compaction,Sleep;internal byte[] Phase;internal Vector3[] Points,Velocities;internal float[] Masses;internal Batch(Settings row){Row=row;State=row["state"].AsGodotDictionary();Settings=row["settings"].AsGodotDictionary();Config=row["config"].AsGodotDictionary();Ids=State["powder_ids"].AsInt32Array();Contacts=State["powder_contacts"].AsInt32Array();Compaction=State["powder_compaction"].AsFloat32Array();Sleep=State["powder_sleep"].AsFloat32Array();Phase=Get(State,"powder_phase",Array.Empty<byte>()).AsByteArray();Points=State["points"].AsVector3Array();Velocities=State["velocities"].AsVector3Array();Masses=State["powder_masses"].AsFloat32Array();}
        internal void Commit(){State["powder_masses"]=Masses;State["powder_contacts"]=Contacts;State["powder_compaction"]=Compaction;State["powder_sleep"]=Sleep;}
    }
    private sealed class Frame
    {
        internal readonly RefCounted Owner;internal readonly GArray Rows;internal readonly Batch[] Batches;internal Vector3[] Positions,Previous,Velocities;internal float[] Radii,Masses,Inverse,Lambdas;internal int[] Owners,Slots,Contacts,Pairs;internal long Checks;internal string Error;
        internal Frame(RefCounted owner){Owner=owner;Rows=owner.Get("batches").AsGodotArray();Batches=Rows.Select(row=>new Batch(row.AsGodotDictionary())).ToArray();Positions=owner.Get("positions").AsVector3Array();Previous=owner.Get("previous").AsVector3Array();Velocities=owner.Get("velocities").AsVector3Array();Radii=owner.Get("radii").AsFloat32Array();Masses=owner.Get("masses").AsFloat32Array();Inverse=owner.Get("inverse_masses").AsFloat32Array();Owners=owner.Get("owners").AsInt32Array();Slots=owner.Get("slots").AsInt32Array();Contacts=owner.Get("contacts").AsInt32Array();Pairs=owner.Get("pairs").AsInt32Array();Lambdas=owner.Get("lambdas").AsFloat32Array();Checks=owner.Get("checks").AsInt64();Error=owner.Get("error").AsString();}
        internal void Commit(){Owner.Set("positions",Positions);Owner.Set("previous",Previous);Owner.Set("velocities",Velocities);Owner.Set("radii",Radii);Owner.Set("masses",Masses);Owner.Set("inverse_masses",Inverse);Owner.Set("owners",Owners);Owner.Set("slots",Slots);Owner.Set("contacts",Contacts);Owner.Set("pairs",Pairs);Owner.Set("lambdas",Lambdas);Owner.Set("checks",Checks);Owner.Set("error",Error);foreach(var batch in Batches)batch.Commit();}
    }
    private static bool Neighbors(Frame f,double maximumRadius){double separation=0;foreach(var batch in f.Batches)if(batch.Settings["cohesion"].AsDouble()>0)separation=Math.Max(separation,batch.Settings["separation"].AsDouble());double cellSize=maximumRadius*2*(1+separation);var grid=new Dictionary<Vector3I,List<int>>();var cells=new Vector3I[f.Positions.Length];for(int i=0;i<f.Positions.Length;i++){var coordinate=(f.Positions[i]/(float)cellSize).Floor();var cell=new Vector3I((int)coordinate.X,(int)coordinate.Y,(int)coordinate.Z);cells[i]=cell;if(!grid.TryGetValue(cell,out var items))grid[cell]=items=new List<int>();items.Add(i);}var pairs=new List<int>();for(int i=0;i<f.Positions.Length;i++){var a=f.Batches[f.Owners[i]];for(int x=-1;x<=1;x++)for(int y=-1;y<=1;y++)for(int z=-1;z<=1;z++)if(grid.TryGetValue(cells[i]+new Vector3I(x,y,z),out var items))foreach(int j in items){if(j<=i)continue;f.Checks++;var b=f.Batches[f.Owners[j]];if(!a.Config["collision"].AsBool()||!b.Config["collision"].AsBool()||(a.Config["layer"].AsInt32()&b.Config["mask"].AsInt32())==0||(b.Config["layer"].AsInt32()&a.Config["mask"].AsInt32())==0)continue;if(f.Positions[i].DistanceSquaredTo(f.Positions[j])>Math.Pow((f.Radii[i]+f.Radii[j])*(1+separation),2))continue;if(pairs.Count>=2000000){f.Error="Excessive grain overlap exceeds the contact budget. Increase source spacing; no grains were discarded.";f.Pairs=pairs.ToArray();return false;}pairs.Add(i);pairs.Add(j);}}f.Pairs=pairs.ToArray();return true;}
    private static void Contact(Frame f,int pair,int iterations,int substeps,bool countContact)
    {
        int i=f.Pairs[pair*2],j=f.Pairs[pair*2+1];double w=f.Inverse[i]+f.Inverse[j];if(w<=0)return;var a=f.Batches[f.Owners[i]];var b=f.Batches[f.Owners[j]];var sa=a.Settings;var sb=b.Settings;double h=Math.Max(.000001,Math.Min(a.Row["moving"].AsBool()?a.Row["h"].AsDouble():b.Row["h"].AsDouble(),b.Row["moving"].AsBool()?b.Row["h"].AsDouble():a.Row["h"].AsDouble())/substeps);var delta=f.Positions[i]-f.Positions[j];double distance=delta.Length();var normal=delta/(float)Math.Max(distance,1e-8);if(distance<1e-8)normal=(i+j)%2==0?Vector3.Right:Vector3.Up;double rest=f.Radii[i]+f.Radii[j],penetration=rest-distance,initialOverlap=rest-(f.Previous[i]-f.Previous[j]).Length();if(f.Lambdas[pair]==0&&initialOverlap>rest*.05){var repair=normal*(float)(initialOverlap/w);f.Previous[i]+=repair*f.Inverse[i];f.Previous[j]-=repair*f.Inverse[j];}if(distance<rest*.9){var hardLimit=normal*(float)((rest*.9-distance)/w);f.Positions[i]+=hardLimit*f.Inverse[i];f.Positions[j]-=hardLimit*f.Inverse[j];penetration=rest*.1;}if(penetration>0||f.Lambdas[pair]>0){double packing=Math.Sqrt(sa["packing"].AsDouble()*sb["packing"].AsDouble()),compliance=Math.Pow(1-packing,2)*.05/(h*h),change=(penetration-compliance*f.Lambdas[pair])/(w+compliance);change=Math.Max(-f.Lambdas[pair],change);f.Lambdas[pair]+=(float)change;f.Positions[i]+=normal*(float)(change*f.Inverse[i]);f.Positions[j]-=normal*(float)(change*f.Inverse[j]);var relative=(f.Positions[i]-f.Previous[i])-(f.Positions[j]-f.Previous[j]);var tangent=relative-normal*relative.Dot(normal);double length=tangent.Length(),support=f.Lambdas[pair]*w,muStatic=Math.Sqrt(sa["static_friction"].AsDouble()*sb["static_friction"].AsDouble()),muDynamic=Math.Sqrt(sa["dynamic_friction"].AsDouble()*sb["dynamic_friction"].AsDouble())+Math.Sqrt(sa["rolling"].AsDouble()*sb["rolling"].AsDouble());if(length>1e-9&&countContact){double fraction=length<muStatic*support?1:Math.Min(1,muDynamic*support/length);var correction=tangent*(float)(fraction/w);f.Positions[i]-=correction*f.Inverse[i];f.Positions[j]+=correction*f.Inverse[j];}if(countContact&&distance<rest*1.03){f.Contacts[i]++;f.Contacts[j]++;}}
        double strength=Math.Sqrt(sa["cohesion"].AsDouble()*sb["cohesion"].AsDouble());string key=a.Ids[f.Slots[i]]+"|"+b.Row["id"].AsString()+"|"+b.Ids[f.Slots[j]];var bonds=a.State["powder_bonds"].AsGodotDictionary();if(strength<=0||distance>rest*(1+Math.Min(sa["separation"].AsDouble(),sb["separation"].AsDouble()))){bonds.Remove(key);return;}if(!bonds.ContainsKey(key)&&distance<=rest*1.1){if(bonds.Count>=65536){f.Error="Cohesive contact storage limit reached. Reduce grain count or cohesion range; grain identities are preserved.";return;}bonds[key]=new Settings{["a"]=a.Ids[f.Slots[i]],["actor"]=b.Row["id"],["b"]=b.Ids[f.Slots[j]],["rest"]=rest};}if(bonds.ContainsKey(key)&&distance>rest){double compact=1+.25*Math.Min(a.Compaction[f.Slots[i]],b.Compaction[f.Slots[j]]);var correction=normal*(float)Math.Min((distance-rest)/w,strength*compact*h*h/iterations);f.Positions[i]-=correction*f.Inverse[i];f.Positions[j]+=correction*f.Inverse[j];}
    }
    private static void VelocityContact(Frame f,int pair,Vector3[] incoming){int i=f.Pairs[pair*2],j=f.Pairs[pair*2+1];double w=f.Inverse[i]+f.Inverse[j];if(w<=0)return;var delta=f.Positions[i]-f.Positions[j];if(delta.LengthSquared()>Math.Pow((f.Radii[i]+f.Radii[j])*1.04,2))return;var normal=delta.Normalized();double speed=(f.Velocities[i]-f.Velocities[j]).Dot(normal);var a=f.Batches[f.Owners[i]].Settings;var b=f.Batches[f.Owners[j]].Settings;double impact=(incoming[i]-incoming[j]).Dot(normal),restitution=impact<-.3?Math.Sqrt(a["restitution"].AsDouble()*b["restitution"].AsDouble()):0,damping=Math.Max(a["contact_damping"].AsDouble(),b["contact_damping"].AsDouble()),target=Math.Max(0,-impact*restitution),change=restitution>0?Math.Max(0,target-speed):Math.Max(0,-speed*damping);var impulse=normal*(float)(change/w);f.Velocities[i]+=impulse*f.Inverse[i];f.Velocities[j]-=impulse*f.Inverse[j];}
    private static void Prune(Frame f){var lookup=new Dictionary<string,int>();for(int i=0;i<f.Positions.Length;i++){var batch=f.Batches[f.Owners[i]];lookup[batch.Row["id"].AsString()+":"+batch.Ids[f.Slots[i]]]=i;}foreach(var batch in f.Batches){var bonds=batch.State["powder_bonds"].AsGodotDictionary();foreach(var key in bonds.Keys.ToArray()){var bond=bonds[key].AsGodotDictionary();if(!lookup.TryGetValue(batch.Row["id"].AsString()+":"+bond["a"].ToString(),out int a)||!lookup.TryGetValue(bond["actor"].AsString()+":"+bond["b"].ToString(),out int b)||batch.Settings["cohesion"].AsDouble()<=0){bonds.Remove(key);continue;}double limit=Math.Min(batch.Settings["separation"].AsDouble(),f.Batches[f.Owners[b]].Settings["separation"].AsDouble());if(f.Positions[a].DistanceTo(f.Positions[b])>bond["rest"].AsDouble()*(1+limit))bonds.Remove(key);}}}
}
